import json,pathlib
root=pathlib.Path('/home/appontrack/public_html/mobile/updates')
out={}
for name in ['latest.json','native/latest.json']:
 p=root/name
 if not p.exists():out[name]={'exists':False};continue
 try:
  v=json.loads(p.read_text())
  meta=json.loads(v.get('payload','{}'))
  out[name]={'exists':True,'revision':meta.get('revision'),'version_code':meta.get('version_code'),'version_name':meta.get('version_name'),'sha256':meta.get('sha256'),'file':meta.get('file')}
 except Exception as e:out[name]={'exists':True,'parse_error':type(e).__name__}
print(json.dumps(out))
